```json
{
  "root_causes": [
    {
      "service": "product-catalog",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'norm' p, count(*) n FROM normal_traces WHERE service_name='product-catalog' UNION ALL SELECT 'abn', count(*) FROM abnormal_traces WHERE service_name='product-catalog'", "claim": "product-catalog emits server spans in the normal period (about 60 per minute) and none at all in the abnormal period."},
        {"kind": "metric", "sql": "SELECT date_trunc('second', time) t, round(avg(value)/1e6,3) rss_mb FROM abnormal_metrics WHERE service_name='product-catalog' AND metric='container.memory.rss' GROUP BY 1 ORDER BY 1 LIMIT 20", "claim": "product-catalog RSS falls from about 13 MB to about 0.3 MB at 02:00 and stays there for the whole window."},
        {"kind": "metric", "sql": "SELECT service_name, attr_k8s_pod_name, metric, min(time) t0, max(time) t1, round(min(value),1) mn, round(max(value),1) mx FROM abnormal_metrics_sum WHERE service_name='product-catalog' AND metric='k8s.pod.uptime' GROUP BY 1,2,3", "claim": "product-catalog pod uptime rises monotonically through the abnormal window, so there was no restart; the process went away and stayed gone."},
        {"kind": "trace", "sql": "SELECT span_name, service_name, attr_status_code, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE span_name IN ('grpc.oteldemo.ProductCatalogService/GetProduct','oteldemo.ProductCatalogService/GetProduct','/oteldemo.ProductCatalogService/ListProducts') AND attr_status_code='Error' GROUP BY 1,2,3", "claim": "Callers of product-catalog (frontend, checkout, recommendation) get Error spans that fail in under 1 ms."},
        {"kind": "trace", "sql": "SELECT count(*) n, round(avg(duration)/1e6,3) avg_ms FROM abnormal_traces WHERE span_name='tcp.connect' AND service_name='frontend' AND attr_status_code='Error'", "claim": "Frontend tcp.connect attempts fail quickly, around 0.4 ms, consistent with the target refusing connections."}
      ]
    }
  ],
  "propagation": [
    {"from": "product-catalog", "to": "frontend", "evidence": [{"kind": "trace", "sql": "SELECT span_name, service_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name='grpc.oteldemo.ProductCatalogService/GetProduct' GROUP BY 1,2,3", "claim": "Frontend's GetProduct calls to product-catalog all return Error (169 spans) in the abnormal period."}]},
    {"from": "product-catalog", "to": "recommendation", "evidence": [{"kind": "trace", "sql": "SELECT span_name, service_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='recommendation' AND span_name='/oteldemo.ProductCatalogService/ListProducts' GROUP BY 1,2,3", "claim": "Recommendation's ListProducts calls to product-catalog fail (37 Error spans) in the abnormal period."}]},
    {"from": "product-catalog", "to": "checkout", "evidence": [{"kind": "trace", "sql": "SELECT span_name, service_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='checkout' AND span_name='oteldemo.ProductCatalogService/GetProduct' GROUP BY 1,2,3", "claim": "Checkout's GetProduct calls to product-catalog fail with Error (18 spans) in the abnormal period."}]},
    {"from": "recommendation", "to": "frontend", "evidence": [{"kind": "trace", "sql": "SELECT span_name, service_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name='GET /api/recommendations' GROUP BY 1,2,3,4", "claim": "Frontend /api/recommendations requests return HTTP 500 (33 spans) after recommendation fails on product-catalog."}]},
    {"from": "checkout", "to": "frontend", "evidence": [{"kind": "trace", "sql": "SELECT span_name, service_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name='grpc.oteldemo.CheckoutService/PlaceOrder' GROUP BY 1,2,3", "claim": "Frontend's PlaceOrder calls to checkout fail (23 Error spans) after checkout's product lookups fail."}]},
    {"from": "frontend", "to": "frontend-proxy", "evidence": [{"kind": "trace", "sql": "SELECT span_name, service_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='router frontend egress' GROUP BY 1,2,3,4", "claim": "Frontend-proxy egress to frontend returns HTTP 500 for 238 requests in the abnormal period, against none in normal traffic."}]}
